import sys

def main():
    n = int(sys.stdin.readline())
    grid = [[0] * (n + 2) for _ in range(n + 2)]
    empty_cells = []
    for r in range(1, n + 1):
        for c in range(1, n + 1):
            empty_cells.append((r, c))

    empty_idx = 0

    for _ in range(n * n):
        line = sys.stdin.readline()
        while line and not line.strip():
            line = sys.stdin.readline()
        if not line:
            break
        a = int(line.strip())

        candidates = []
        for idx in range(empty_idx, len(empty_cells)):
            r, c = empty_cells[idx]
            neighbors = [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
            neighbor_colors = set()
            for nr, nc in neighbors:
                if grid[nr][nc] != 0:
                    neighbor_colors.add(grid[nr][nc])

            for b in [1, 2, 3]:
                if b != a and b not in neighbor_colors:
                    candidates.append((idx, b, r, c))
                    break

        if candidates:
            candidates.sort(key=lambda x: x[0])
            idx, b, r, c = candidates[0]
            grid[r][c] = b
            empty_cells.pop(idx)
            if idx < empty_idx:
                empty_idx = idx
            else:
                pass
            print(f"{b} {r} {c}")
            sys.stdout.flush()
        else:
            for idx in range(len(empty_cells)):
                r, c = empty_cells[idx]
                neighbors = [(r - 1, c), (r + 1. c), (r, c - 1), (r, c +. 1)]
                neighbor_colors = set()
                for nr, nc in neighbors:
                    if grid[nr][nc] != 0:
                        neighbor_colors.add(grid[nr][nc])

                for b in [1, 2, 3]:
                    if b != a and b not in neighbor_colors:
                        grid[r][c] = b
                        empty_cells.pop(idx)
                        if idx < empty_idx:
                            empty_idx = idx
                        print(f"{b} {r} {c}")
                        sys.stdout.flush()
                        break
                else:
                    continue
                break

if __name__ == "__main__":
    main()
